CREATE TABLE Roles (RoleId UNIQUEIDENTIFIER PRIMARY KEY DEFAULT NEWID(), Name NVARCHAR(50) NOT NULL UNIQUE);
INSERT INTO Roles (Name) VALUES ('User'), ('Admin'), ('TradingOperator'), ('SettlementOperator');
CREATE TABLE UserRoles (UserId UNIQUEIDENTIFIER NOT NULL FOREIGN KEY REFERENCES Users(UserId), RoleId UNIQUEIDENTIFIER NOT NULL FOREIGN KEY REFERENCES Roles(RoleId), PRIMARY KEY (UserId, RoleId));
CREATE INDEX IX_Users_Email ON Users(Email);
CREATE OR ALTER PROCEDURE dbo.usp_User_Register @UserId UNIQUEIDENTIFIER, @Email NVARCHAR(320), @PasswordHash NVARCHAR(512), @WalletId UNIQUEIDENTIFIER, @InitialBalance DECIMAL(19,4) = 10000.00 AS BEGIN SET NOCOUNT ON; SET XACT_ABORT ON; BEGIN TRANSACTION; IF EXISTS (SELECT 1 FROM Users WHERE Email = @Email) BEGIN ROLLBACK; THROW 50010, 'Email already registered', 1; END INSERT INTO Users (UserId, Email, PasswordHash) VALUES (@UserId, @Email, @PasswordHash); DECLARE @UserRoleId UNIQUEIDENTIFIER = (SELECT RoleId FROM Roles WHERE Name = 'User'); INSERT INTO UserRoles (UserId, RoleId) VALUES (@UserId, @UserRoleId); INSERT INTO Wallets (WalletId, UserId, CurrencyCode) VALUES (@WalletId, @UserId, 'NGN'); INSERT INTO WalletLedgerEntries (LedgerEntryId, WalletId, EntryType, Amount, ReferenceType, ReferenceId, IdempotencyKey) VALUES (NEWID(), @WalletId, 'Credit_SignupBonus_Simulated', @InitialBalance, 'Signup', @UserId, 'SIGNUP_' + CAST(@UserId AS NVARCHAR(50))); COMMIT; END
